package service
import("context";"encoding/json";"fmt";"github.com/google/uuid";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/pgxpool";"github.com/openoms-org/openoms/apps/api-server/internal/database";"github.com/openoms-org/openoms/apps/api-server/internal/repository")
type shopeeResolvedOrderItem struct{ProductID string `json:"product_id"`;VariantID string `json:"variant_id,omitempty"`;Quantity int `json:"quantity"`}
type ShopeeInventoryResult struct{Adjusted,BundleComponents,Skipped int}
type ShopeeInventoryService struct{pool *pgxpool.Pool;warehouses *repository.WarehouseRepository;stock *repository.WarehouseStockRepository;bundles *repository.BundleRepository}
func NewShopeeInventoryService(pool *pgxpool.Pool)*ShopeeInventoryService{return &ShopeeInventoryService{pool:pool,warehouses:repository.NewWarehouseRepository(),stock:repository.NewWarehouseStockRepository(),bundles:repository.NewBundleRepository()}}
func(s *ShopeeInventoryService)DeductOrder(ctx context.Context,tenantID,integrationID uuid.UUID,externalOrderID string,itemsJSON json.RawMessage)(*ShopeeInventoryResult,error){result:=&ShopeeInventoryResult{};err:=database.WithTenant(ctx,s.pool,tenantID,func(tx pgx.Tx)error{tag,err:=tx.Exec(ctx,"INSERT INTO marketplace_order_inventory_events(id,tenant_id,integration_id,external_order_id,event_type) VALUES($1,$2,$3,$4,'deduct') ON CONFLICT DO NOTHING",uuid.New(),tenantID,integrationID,externalOrderID);if err!=nil{return err};if tag.RowsAffected()==0{return nil};wh,err:=s.warehouses.FindDefault(ctx,tx);if err!=nil{return err};if wh==nil{return fmt.Errorf("default warehouse not configured")};var items []shopeeResolvedOrderItem;if err:=json.Unmarshal(itemsJSON,&items);err!=nil{return err};for _,it:=range items{if it.ProductID==""||it.Quantity<=0{result.Skipped++;continue};productID,err:=uuid.Parse(it.ProductID);if err!=nil{result.Skipped++;continue};var variantID *uuid.UUID;if it.VariantID!=""{v,e:=uuid.Parse(it.VariantID);if e==nil{variantID=&v}};components,err:=s.bundles.ListByBundleProduct(ctx,tx,productID);if err!=nil{return err};if len(components)>0{for _,c:=range components{if err:=s.stock.AdjustQuantity(ctx,tx,wh.ID,c.ComponentProductID,c.ComponentVariantID,-(it.Quantity*c.Quantity));err!=nil{return err};result.BundleComponents++};continue};if err:=s.stock.AdjustQuantity(ctx,tx,wh.ID,productID,variantID,-it.Quantity);err!=nil{return err};result.Adjusted++};return nil});if err!=nil{return nil,fmt.Errorf("shopee inventory deduction: %w",err)};return result,nil}
